head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > P > contextMenu]<br/>Body 영역에서 마우스 우클릭 시 WebSquare 컨텍스트 메뉴를 표시할지 설정합니다.",
    "validation" : [
        "true 설정 시 Body 영역에서 마우스 우클릭 시 WebSquare 컨텍스트 메뉴를 표시해야 합니다.",
        "미설정 또는 false 설정 시 Body 영역에서 마우스 우클릭 시 WebSquare 컨텍스트 메뉴를 표시하지 않아야 합니다. (기본값 false)",
        "WebSquare 컨텍스트 메뉴는 기본 12 개 항목을 제공하며 GridView 의 현재 상태에 맞는 메뉴만 표시되어야 합니다.",
        "컨텍스트 메뉴창엔 'w2grid_contextMenu' CSS 클래스가 설정되어야 합니다.",
        "contextMenu 속성값에 관계없이 Header 와 Body 영역에서 마우스 우클릭 시 웹브라우저의 기본 컨텍스트 메뉴는 표시되지 않아야 합니다."
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target / dataList 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 안내 라벨 (가장 먼저 생성)
    $c.gcm.createLabel('label="Body(데이터 셀) 영역을 마우스 우클릭하여 WebSquare 컨텍스트 메뉴 표시 여부를 확인하세요. true 설정 시에만 메뉴가 표시됩니다."', '', 'label1');

    // 조건 설정
    //  - con_contextMenu 가 미설정('') 이면 createCList 가 빈 문자열 value 를 자동 제외하므로
    //    properties 키 자체가 빠짐 → contextMenu 속성을 소스에 미설정한 케이스 (기본값 false 동작)
    let properties = {
        dataList: "data:dlt_bind",
        contextMenu: con_contextMenu.getValue()
    };

    let cList = $c.gcm.createCList(properties);

    // oncontextopen 이벤트 핸들러 부착
    //  - contextMenu 속성 효과(메뉴 표시/클래스/항목)를 검증하기 위한 출력 용도로만 사용
    let eList = $c.gcm.createEList(["oncontextopen"]);

    // dataList 생성 (기본 데이터 바인딩)
    $c.gcm.createBasicDataList('', '', 'dlt_bind');

    // target 생성
    await $c.gcm.createBasicGridView(cList, eList);
}



// oncontextopen : Body 우클릭으로 WebSquare 컨텍스트 메뉴가 표시될 때 발생
//  - 본 핸들러는 contextMenu=true 효과(메뉴 표시 / w2grid_contextMenu 클래스 / 현재 상태 메뉴 항목)를 검증하기 위한 출력 용도
//  - 메뉴 DOM 은 oncontextopen 이후 생성되므로 setTimeout(0) 으로 생성 후 검증
//  - 순환 검증 방지를 위해 list 컴포넌트 id(_contextMenu_list)로 탐색한 뒤 w2grid_contextMenu 클래스 설정 여부를 확인
scwin.target1_oncontextopen = function (rowIndex, columnIndex, focusedCellInfo, info) {
    setTimeout(function () {
        let menu = document.querySelector("[id$='_contextMenu_list']");
        if (!menu) {
            wf_body_bottom.getObj("scwin").setReturnValue("Body 우클릭 - 컨텍스트 메뉴 미생성");
            return;
        }
        wf_body_bottom.getObj("scwin").setReturnValue("Body 우클릭 - 컨텍스트 메뉴 표시됨");
        wf_body_bottom.getObj("scwin").setReturnValue("'w2grid_contextMenu' 클래스 설정 여부 : " + menu.classList.contains("w2grid_contextMenu"));
        let rows = menu.querySelectorAll(".w2grid_contextMenu_row");
        wf_body_bottom.getObj("scwin").setReturnValue("현재 상태에 맞게 표시된 메뉴 항목 수 : " + rows.length);
    }, 0);
};
